    resp = client.put(
        f"/tasks/{created['id']}",
        json={"status": "in_progress"},
        headers={"Authorization": f"Bearer {token_a}"},
    )
    assert resp.status_code == 200
    data = resp.get_json()
    assert data["status"] == "in_progress"
